class NomAllah {
  final int number;
  final String arabic;
  final String phonetic;
  final String meaning;
  final String explanation;
  final String bienfait;
  const NomAllah({required this.number, required this.arabic, required this.phonetic, required this.meaning, required this.explanation, required this.bienfait});
}

const List<NomAllah> kNomsAllah = [
  NomAllah(number: 1, arabic: 'الرَّحْمَنُ', phonetic: 'Ar-Rahman', meaning: 'Le Tout Miséricordieux', explanation: 'Celui qui couvre l\'univers entier de sa miséricorde infinie, qui nourrit et pourvoit à tous les êtres créés. C\'est la miséricorde englobante et générale qui s\'étend avant même le mérite.', bienfait: 'Celui qui répète ce nom 100 fois le vendredi verra l\'amour et l\'affection se manifester dans son cœur et sa vie.'),
  NomAllah(number: 2, arabic: 'الرَّحِيمُ', phonetic: 'Ar-Rahim', meaning: 'Le Très Miséricordieux', explanation: 'Celui qui manifeste sa miséricorde particulière envers ses serviteurs repentants et croyants. C\'est la miséricorde spéciale accordée après les actes de désobéissance et de repentance sincère.', bienfait: 'Réciter ce nom avec intention sincère après chaque acte répréhensible attire le pardon et purifie l\'âme du serviteur.'),
  NomAllah(number: 3, arabic: 'الْمَلِكُ', phonetic: 'Al-Malik', meaning: 'Le Souverain', explanation: 'Celui qui règne sur toute création avec une autorité absolue, dont le pouvoir ne peut être contesté et dont la royauté n\'a ni début ni fin. Tout est soumis à son pouvoir et à sa domination.', bienfait: 'Méditer sur ce nom apaise le cœur des inquiétudes terrestres et renforce la confiance en la justice divine.'),
  NomAllah(number: 4, arabic: 'الْقُدُّوسُ', phonetic: 'Al-Quddus', meaning: 'Le Saint', explanation: 'Celui qui est complètement purifié de tout défaut, imperfection et limitation. Il est au-delà de toute ressemblance avec la création, absolument sacré et transcendant.', bienfait: 'Celui qui demande la purification spirituelle en répétant ce nom verra son âme s\'élever et ses défauts internes diminuer progressivement.'),
  NomAllah(number: 5, arabic: 'السَّلَامُ', phonetic: 'As-Salam', meaning: 'La Paix', explanation: 'Celui qui est la source de toute paix et sécurité, qui préserve sa création de la destruction et de l\'anéantissement. Il accorde la sécurité à celui qui cherche son refuge.', bienfait: 'Celui qui dit ce nom chaque matin trouvera la sécurité et la tranquillité à travers sa journée malgré les perturbations du monde.'),
  NomAllah(number: 6, arabic: 'الْمُؤْمِنُ', phonetic: 'Al-Moumen', meaning: 'Celui Qui Assure', explanation: 'Celui qui préserve ses créatures et leurs croyances, qui est témoin de la vérité et confirme les paroles véridiques. Il est la source de confiance et d\'assurance pour les croyants.', bienfait: 'Réciter ce nom augmente la foi et protège le croyant des doutes et de l\'égarement spirituel.'),
  NomAllah(number: 7, arabic: 'الْعَزِيزُ', phonetic: 'Al-Aziz', meaning: 'Le Tout-Puissant', explanation: 'Celui dont la force et la puissance sont irrésistibles, dont personne ne peut vaincre ou surpasser. Son honneur et sa dignité sont absolus et inviolables.', bienfait: 'Celui qui invoque ce nom avec sincérité sera aidé face à l\'oppression et trouvera la force de surmonter les obstacles.'),
  NomAllah(number: 8, arabic: 'الْجَبَّارُ', phonetic: 'Al-Jabbar', meaning: 'Le Contraignant', explanation: 'Celui qui impose sa volonté avec puissance absolue, qui contraint et subjugue toute rébellion. C\'est aussi celui qui répare et restaure ce qui est brisé chez ses serviteurs.', bienfait: 'Méditer sur ce nom inspire l\'humilité devant la volonté divine et apaise la fierté de l\'âme égotiste.'),
  NomAllah(number: 9, arabic: 'الْمُتَكَبِّرُ', phonetic: 'Al-Mutakabbir', meaning: 'Le Superbe', explanation: 'Celui qui possède la grandeur suprême et la majesté absolue, qui transcende toute création par son essence. Il est au-delà de toute comparaison et de toute ressemblance.', bienfait: 'Réciter ce nom régulièrement purifie le cœur de l\'orgueil et de la vantardise personnelle.'),
  NomAllah(number: 10, arabic: 'الْخَالِقُ', phonetic: 'Al-Khaliq', meaning: 'Le Créateur', explanation: 'Celui qui a créé toute existence du néant et qui continue à créer sans cesse. Il est l\'unique créateur dont aucune création ne partage cette capacité divine.', bienfait: 'Celui qui médite sur ce nom verra son émerveillement face à la création grandir et son cœur s\'emplir de gratitude.'),
  NomAllah(number: 11, arabic: 'الْبَارِئُ', phonetic: 'Al-Bari', meaning: 'L\'Inventeur', explanation: 'Celui qui façonne et invente les créations avec perfection et sagesse. Il donna à chaque créature sa forme et sa nature spécifiques selon un dessein divin.', bienfait: 'Réciter ce nom aide à accepter sa création et son apparence avec contentement et reconnaissance.'),
  NomAllah(number: 12, arabic: 'الْمُصَوِّرُ', phonetic: 'Al-Musawwir', meaning: 'Le Formateur', explanation: 'Celui qui donne la forme et l\'apparence à toutes les créatures avec harmonie et beauté. Il ne cesse de façonner les formes conformément à sa sagesse infinie.', bienfait: 'Celui qui invoque ce nom pour demander une amélioration personnelle verra son caractère et son apparence s\'améliorer graduellement.'),
  NomAllah(number: 13, arabic: 'الْغَفَّارُ', phonetic: 'Al-Ghaffar', meaning: 'Celui Qui Pardonne', explanation: 'Celui qui efface et pardonne les péchés de ses serviteurs à maintes reprises, malgré leurs transgressions continuelles. Son pardon est vaste comme l\'océan.', bienfait: 'Celui qui se repent sincèrement en invoquant ce nom trouvera la paix de l\'âme et la libération du fardeau de la culpabilité.'),
  NomAllah(number: 14, arabic: 'الْقَهَّارُ', phonetic: 'Al-Qahhar', meaning: 'Le Dominateur', explanation: 'Celui dont la domination absolue s\'exerce sur toute créature qui ne peut lui résister ou échapper à son pouvoir. Tous sont soumis à sa volonté irrésistible.', bienfait: 'Méditer sur ce nom renforce la conscience que toute puissance vient de Dieu et éloigne la dépendance aux causes secondaires.'),
  NomAllah(number: 15, arabic: 'الْوَهَّابُ', phonetic: 'Al-Wahhab', meaning: 'Celui Qui Donne', explanation: 'Celui qui donne généreusement sans compter, dont les dons sont innombrables et continus. Il donne à qui il veut sans rétribution ou obligation.', bienfait: 'Celui qui invoque ce nom avec reconnaissance verra les bienfaits et les provisions se multiplier dans sa vie.'),
  NomAllah(number: 16, arabic: 'الرَّزَّاقُ', phonetic: 'Ar-Razzaq', meaning: 'Celui Qui Pourvoit', explanation: 'Celui qui nourrit et pourvoit à la subsistance de toute créature. Il est la source de toute provision et de tout bénéfice dans ce monde et l\'autre.', bienfait: 'Réciter ce nom avec confiance et sincérité attire la subsistance et éloigne la pauvreté et l\'inquiétude matérielle.'),
  NomAllah(number: 17, arabic: 'الْفَتَّاحُ', phonetic: 'Al-Fattah', meaning: 'L\'Ouvreur', explanation: 'Celui qui ouvre les portes du succès, de la connaissance et du pardon. Il tranche entre les créatures en jugement et déverrouille les mystères de l\'existence.', bienfait: 'Celui qui récite ce nom en début de jour verra les portes des opportunités et des solutions s\'ouvrir devant lui.'),
  NomAllah(number: 18, arabic: 'الْعَلِيمُ', phonetic: 'Al-Alim', meaning: 'L\'Omniscient', explanation: 'Celui dont la science englobe tous les choses, du passé jusqu\'au futur, du visible à l\'invisible. Sa connaissance est absolue et sans limite.', bienfait: 'Celui qui médite sur ce nom prend conscience que rien ne peut lui être caché de Dieu et cela renforce son intégrité morale.'),
  NomAllah(number: 19, arabic: 'الْقَابِضُ', phonetic: 'Al-Qabid', meaning: 'Celui Qui Restreint', explanation: 'Celui qui restreint les provisions et les bienfaits selon sa sagesse, et qui peut retirer ce qu\'il a accordé. Cette restriction peut être un test ou une miséricorde cachée.', bienfait: 'Accepter ce nom avec patience renforce la contentement et protège le cœur de l\'avidité et du désir immodéré.'),
  NomAllah(number: 20, arabic: 'الْبَاسِطُ', phonetic: 'Al-Basit', meaning: 'Celui Qui Étend', explanation: 'Celui qui étend et augmente les provisions et les bienfaits selon sa volonté. Il donne l\'expansion et la largeur à celui qui il veut favori.', bienfait: 'Invoquer ce nom attire l\'abundance et l\'aisance matérielle et spirituelle dans la vie du serviteur.'),
  NomAllah(number: 21, arabic: 'الْخَافِضُ', phonetic: 'Al-Khafid', meaning: 'Celui Qui Abaisse', explanation: 'Celui qui abaisse l\'orgueilleux et l\'arrogant, qui rabaisse celui qui s\'élève injustement. C\'est aussi celui qui abaisse les rangs des pécheurs impénitents.', bienfait: 'Celui qui tient ce nom en mémoire verra son orgueil diminuer et son cœur s\'incliner dans l\'humilité devant la divinité.'),
  NomAllah(number: 22, arabic: 'الرَّافِعُ', phonetic: 'Ar-Rafi', meaning: 'Celui Qui Élève', explanation: 'Celui qui élève le rang des croyants sincères et des obéissants, qui augmente leur dignité et leur honneur. Il élève aussi les âmes vers la perfection spirituelle.', bienfait: 'Méditer sur ce nom inspire le désir d\'amélioration personnelle et d\'ascension spirituelle constante.'),
  NomAllah(number: 23, arabic: 'الْمُعِزُّ', phonetic: 'Al-Muiz', meaning: 'Celui Qui Honore', explanation: 'Celui qui confère l\'honneur et la dignité à qui il veut. Son honneur accordé ne peut être diminué par personne d\'autre.', bienfait: 'Invoquer ce nom avec sincérité apporte l\'honneur véritable qui ne dépend pas du jugement des hommes.'),
  NomAllah(number: 24, arabic: 'الْمُذِلُّ', phonetic: 'Al-Mudhill', meaning: 'Celui Qui Humilie', explanation: 'Celui qui abaisse celui qui devient arrogant et orgueilleux. Son humiliation peut être une correction ou un test pour rectifier la conduite du serviteur.', bienfait: 'Accepter ce nom avec sagesse protège du destin des arrogants et maintient l\'humilité du cœur.'),
  NomAllah(number: 25, arabic: 'السَّمِيعُ', phonetic: 'As-Sami', meaning: 'L\'Omniscient', explanation: 'Celui qui entend toutes les paroles et les invocations de ses créatures, même chuchotées secrètement. Son ouïe englobe tout et ne manque rien.', bienfait: 'Celui qui sait que Dieu l\'écoute toujours parlera avec sagesse et purifiera son discours de la médisance.'),
  NomAllah(number: 26, arabic: 'الْبَصِيرُ', phonetic: 'Al-Basir', meaning: 'Le Voyant', explanation: 'Celui qui voit tout ce qui existe, du plus grand au plus petit, du caché au manifeste. Sa vision pénètre toutes les profondeurs et aucun secret ne lui est dissimulé.', bienfait: 'Sachant que Dieu le voit toujours, le serviteur s\'abstiendra de l\'interdit et cultivera les bonnes actions.'),
  NomAllah(number: 27, arabic: 'الْحَكِيمُ', phonetic: 'Al-Hakim', meaning: 'Le Sage', explanation: 'Celui dont la sagesse est absolue et parfaite en toutes choses. Chacun de ses actes, ses commandements et ses décrets reflètent une sagesse cachée et profonde.', bienfait: 'Méditer sur ce nom enseigne l\'acceptation des décrets divins même quand la sagesse en est cachée à la raison humaine.'),
  NomAllah(number: 28, arabic: 'الْعَظِيمُ', phonetic: 'Al-Azim', meaning: 'Le Magnifique', explanation: 'Celui dont la grandeur et la magnificence surpassent toute conception. Sa gloire englobe tout et rien ne peut lui être égalé en sublimité.', bienfait: 'Réciter ce nom rend humble et remplit l\'âme d\'une admiration profonde pour la grandeur divine.'),
  NomAllah(number: 29, arabic: 'الْغَفُورُ', phonetic: 'Al-Ghafur', meaning: 'Celui Qui Pardonne', explanation: 'Celui qui pardonne les péchés malgré leur nombre et leur gravité, et qui voile les fautes de ses serviteurs. Son pardon couvre tout pour celui qui se repent.', bienfait: 'Celui qui confesse ses péchés en invoquant ce nom trouvera l\'absolution et la paix intérieure restaurée.'),
  NomAllah(number: 30, arabic: 'الشَّكُورُ', phonetic: 'Ash-Shakur', meaning: 'Celui Qui Récompense', explanation: 'Celui qui reconnaît et récompense généreusement les bonnes actions, même les plus petites. Il multiplie les récompenses et ne permet pas que l\'effort sincère soit perdu.', bienfait: 'Celui qui remercie Dieu sincèrement verra ses bienfaits se multiplier et sa gratitude renforcée continuellement.'),
  NomAllah(number: 31, arabic: 'الْعَلِيُّ', phonetic: 'Al-Ali', meaning: 'Le Très-Haut', explanation: 'Celui qui est au-dessus de toute création tant en essence qu\'en pouvoir et en sagesse. Son élévation est absolue et rien ne s\'égale à sa hauteur.', bienfait: 'Celui qui contemple ce nom reconnaît la limite de sa propre condition et renforce son besoin de proximité avec le divin.'),
  NomAllah(number: 32, arabic: 'الْكَبِيرُ', phonetic: 'Al-Kabir', meaning: 'Le Grand', explanation: 'Celui dont la grandeur est infinie et incommensurable. Toute grandeur créée est insignifiante comparée à la grandeur divine.', bienfait: 'Méditer sur ce nom apaise les soucis terrestres en rappelant que toute difficulté est petite face à la grandeur de Dieu.'),
  NomAllah(number: 33, arabic: 'الْحَفِيظُ', phonetic: 'Al-Hafiz', meaning: 'Le Préservateur', explanation: 'Celui qui préserve et garde toute création du changement, de la destruction et de l\'oubli. Il protège ses serviteurs croyants de tous les malheurs.', bienfait: 'Celui qui confie ses affaires à ce nom sera protégé et préservé de tout mal par la grâce divine.'),
  NomAllah(number: 34, arabic: 'الْمُقِيتُ', phonetic: 'Al-Muqit', meaning: 'Celui Qui Nourrit', explanation: 'Celui qui nourrit et soutient toute existence, qui pourvoit aux besoins de chaque créature. Il est la source continue de subsistance et de force.', bienfait: 'Invoquer ce nom attire les provisions suffisantes et renforce la confiance en l\'entretien de Dieu pour le serviteur.'),
  NomAllah(number: 35, arabic: 'الْحَسِيبُ', phonetic: 'Al-Hasib', meaning: 'Celui Qui Compte', explanation: 'Celui qui compte les actes de ses serviteurs et les connaît en détail, qui sera suffisant le Jour du Jugement. Il suffit comme témoin et comme juge.', bienfait: 'Celui qui sait que Dieu compte ses actes révèlera son intention en chaque affaire et purifiera ses motivations.'),
  NomAllah(number: 36, arabic: 'الْجَلِيلُ', phonetic: 'Al-Jalil', meaning: 'Le Majestueux', explanation: 'Celui dont la majesté et la splendeur inspirent la crainte révérencielle. Sa majesté transcende toute conception de grandeur créée.', bienfait: 'Contempler ce nom remplit le cœur d\'une crainte respectueuse qui purifie l\'âme de la rébellion.'),
  NomAllah(number: 37, arabic: 'الْكَرِيمُ', phonetic: 'Al-Karim', meaning: 'Le Généreux', explanation: 'Celui dont la générosité est infinie et inépuisable, qui donne sans mesure. Sa noblesse et sa magnanimité se manifestent dans chacun de ses bienfaits.', bienfait: 'Celui qui demande avec sincérité en invoquant ce nom verra la générosité divine s\'accumuler dans sa vie.'),
  NomAllah(number: 38, arabic: 'الرَّقِيبُ', phonetic: 'Ar-Raqib', meaning: 'Le Surveillant', explanation: 'Celui qui surveille toutes les créatures et observe tous leurs actes, secrets et manifestes. Rien ne peut lui échapper ou lui être caché.', bienfait: 'Sachant qu\'il est observé par Dieu, le serviteur modèrera ses actes et cultivera la sincérité en toutes circonstances.'),
  NomAllah(number: 39, arabic: 'الْمُجِيبُ', phonetic: 'Al-Mujib', meaning: 'Celui Qui Exauce', explanation: 'Celui qui exauce les invocations et les demandes sincères de ses serviteurs. Il écoute et répond à celui qui l\'appelle avec un cœur sincère.', bienfait: 'Celui qui invoque ce nom avec sincérité et confiance verra ses prières exaucées selon ce qui est mieux pour lui.'),
  NomAllah(number: 40, arabic: 'الْوَاسِعُ', phonetic: 'Al-Wasi', meaning: 'L\'Infini', explanation: 'Celui dont la science, la puissance et la miséricorde englobent tout. Son infini transcende toute limite créée.', bienfait: 'Celui qui médite sur ce nom trouvera la consolation en sachant que l\'aide de Dieu est aussi vaste que ses difficultés.'),
  NomAllah(number: 41, arabic: 'الْحَكِيمُ', phonetic: 'Al-Hakim', meaning: 'Le Sage', explanation: 'Celui dont la sagesse est absolue dans ses décrets et ses actes. Chaque choix divin reflète une profonde sagesse souvent cachée à la raison humaine.', bienfait: 'Accepter ce nom avec confiance apaise le cœur lors des épreuves en se souvenant que la sagesse divine en transcende les apparences.'),
  NomAllah(number: 42, arabic: 'الْوَدُودُ', phonetic: 'Al-Wadud', meaning: 'Celui Qui Aime', explanation: 'Celui dont l\'amour pour ses serviteurs pieux est constant et profond. C\'est aussi celui qui inspire l\'amour et la tendresse entre ses créatures.', bienfait: 'Celui qui invoque ce nom avec un cœur pur attirera l\'amour et l\'affection sincère des gens et de la part de Dieu.'),
  NomAllah(number: 43, arabic: 'الْمَجِيدُ', phonetic: 'Al-Majid', meaning: 'Le Glorieux', explanation: 'Celui dont la gloire et l\'honneur sont suprêmes et inviolables. Sa magnificence engendre la gloire de toute création.', bienfait: 'Réciter ce nom honore le serviteur et élève son statut parmi les créatures tout en lui rappelant que toute gloire émane de Dieu.'),
  NomAllah(number: 44, arabic: 'الْبَاعِثُ', phonetic: 'Al-Baes', meaning: 'Celui Qui Ressuscite', explanation: 'Celui qui ressuscitera tous les hommes le Jour du Jugement Dernier. C\'est aussi celui qui suscite le bien et la guidance chez ses serviteurs.', bienfait: 'Méditer sur ce nom renforce la foi au Jugement Dernier et encourage l\'action vertueuse pour la vie éternelle.'),
  NomAllah(number: 45, arabic: 'الشَّهِيدُ', phonetic: 'Ash-Shahid', meaning: 'Le Témoin', explanation: 'Celui qui est témoin de tous les actes et paroles des créatures. Il sera le témoin suprême le Jour du Jugement contre ou en faveur de chacun.', bienfait: 'Sachant que Dieu est témoin de ses actes, le serviteur maintiendra l\'intégrité morale en toute circonstance.'),
  NomAllah(number: 46, arabic: 'الْحَقُّ', phonetic: 'Al-Haq', meaning: 'La Vérité', explanation: 'Celui qui est la Vérité absolue et dont toute vérité émane. L\'existence même dépend de sa vérité incontestable.', bienfait: 'Celui qui recherche la vérité sincèrement sera guidé vers le chemin droit par la guidance de ce nom divin.'),
  NomAllah(number: 47, arabic: 'الْوَكِيلُ', phonetic: 'Al-Wakil', meaning: 'Celui Qui Pourvoit', explanation: 'Celui sur qui on place sa confiance absolue et à qui on confie ses affaires. Il s\'occupe des intérêts de celui qui se confie à Lui.', bienfait: 'Celui qui remet ses affaires entièrement à Dieu en invoquant ce nom trouvera la paix de l\'âme et le succès.'),
  NomAllah(number: 48, arabic: 'الْقَوِيُّ', phonetic: 'Al-Qawi', meaning: 'Le Puissant', explanation: 'Celui dont la force et la puissance sont absolues et irresistibles. Aucune force créée ne peut s\'opposer à sa puissance.', bienfait: 'Invoquer ce nom renforce le serviteur face aux défis de la vie en lui rappelant qu\'il peut puiser dans la puissance divine.'),
  NomAllah(number: 49, arabic: 'الْمَتِينُ', phonetic: 'Al-Matin', meaning: 'Le Très-Fort', explanation: 'Celui dont la force est extrêmement ferme et inébranlable. Sa fermeté absolue soutient tout l\'univers sans jamais fléchir.', bienfait: 'Celui qui demande la fermeté de conviction en invoquant ce nom renforcera sa foi face aux tentations et aux doutes.'),
  NomAllah(number: 50, arabic: 'الْوَلِيُّ', phonetic: 'Al-Wali', meaning: 'Le Protecteur', explanation: 'Celui qui protège et soutient ses croyants, qui est leur allié et leur auxiliaire. Il est plus proche du serviteur que lui-même.', bienfait: 'Celui qui prend ce nom pour protecteur sera gardé de tout mal et trouvera l\'assistance divine dans les moments critiques.'),
  NomAllah(number: 51, arabic: 'الْحَمِيدُ', phonetic: 'Al-Hamid', meaning: 'Le Louangé', explanation: 'Celui qui est digne de louanges absolues et perpétuelles malgré la présence ou l\'absence de créatures pour le louer. Toute existence le loue.', bienfait: 'Celui qui loue ce nom régulièrement verra la gratitude se multiplier dans son cœur et embellira sa relation avec le créateur.'),
  NomAllah(number: 52, arabic: 'الْمُحْصِي', phonetic: 'Al-Muhsi', meaning: 'Celui Qui Compte', explanation: 'Celui qui dénombre tous les éléments créés, du grain de sable à l\'étoile. Chaque créature est connue par Lui en nombre et en détail.', bienfait: 'Ce nom rappelle que rien ne s\'échappe au compte de Dieu, inspirant la conscience morale et l\'honnêteté.'),
  NomAllah(number: 53, arabic: 'الْمُبْدِئُ', phonetic: 'Al-Mubdi', meaning: 'Celui Qui Crée Initialement', explanation: 'Celui qui crée les choses la première fois en les amenant du néant à l\'existence. C\'est le début de toute création.', bienfait: 'Méditer sur ce nom inspire l\'émerveillement devant la création originelle et renforce la confiance en la puissance créatrice.'),
  NomAllah(number: 54, arabic: 'الْمُعِيدُ', phonetic: 'Al-Mueed', meaning: 'Celui Qui Restaure', explanation: 'Celui qui ramène les choses à l\'existence après leur destruction ou mort. Il renouvelle et restaure continuellement la création.', bienfait: 'Invoquer ce nom apaise les craintes de la mort en se souvenant que la résurrection est aussi certainement possible que la création.'),
  NomAllah(number: 55, arabic: 'الْمُحْيِي', phonetic: 'Al-Muhyi', meaning: 'Celui Qui Vivifie', explanation: 'Celui qui donne la vie à la matière inerte et qui vivifie l\'âme par la foi et la guidance. Il est source de vie éternelle.', bienfait: 'Celui qui demande la vivification du cœur en invoquant ce nom verra sa vie spirituelle s\'enrichir et son énergie se renouveler.'),
  NomAllah(number: 56, arabic: 'الْمُمِيتُ', phonetic: 'Al-Mumit', meaning: 'Celui Qui Cause la Mort', explanation: 'Celui qui ôte la vie et cause la mort de toute créature vivante. La mort n\'existe que par sa volonté et son pouvoir.', bienfait: 'Accepter ce nom avec sagesse apaise la peur de la mort en la reconnaissant comme une transition vers une autre existence.'),
  NomAllah(number: 57, arabic: 'الْحَيُّ', phonetic: 'Al-Hayy', meaning: 'Le Vivant', explanation: 'Celui qui possède la vie éternelle en lui-même sans dépendre d\'une source externe. Sa vie est absolue et inépuisable.', bienfait: 'Réciter ce nom purifie le cœur en le connectant à la source éternelle de vie et en libérant la peur de l\'extinction.'),
  NomAllah(number: 58, arabic: 'الْقَيُّومُ', phonetic: 'Al-Qayyum', meaning: 'L\'Autosuffisant', explanation: 'Celui qui subsiste par lui-même et dont l\'existence dépend uniquement de sa propre essence. Toute autre existence dépend de Lui.', bienfait: 'Celui qui médite sur ce nom comprendra que toute dépendance créée provient ultimement de Dieu et non des autres.'),
  NomAllah(number: 59, arabic: 'الْوِتْرُ', phonetic: 'Al-Witr', meaning: 'L\'Unique', explanation: 'Celui qui est sans égal et sans pareil, l\'unique en essence, attributs et actions. Il n\'a ni associé ni similaire.', bienfait: 'Ce nom protège celui qui le récite de la tendance à associer d\'autres à Dieu et renforce l\'unicité divine dans le cœur.'),
  NomAllah(number: 60, arabic: 'الْفَرْدُ', phonetic: 'Al-Fard', meaning: 'L\'Unique', explanation: 'Celui qui est seul et isolé dans son pouvoir, sa domination et ses attributs. Nul ne peut le égaler ou le partager dans sa divinité.', bienfait: 'Invoquer ce nom renforce l\'isolement spirituel du serviteur de tout ce qui n\'est pas Dieu et purifie son intention.'),
  NomAllah(number: 61, arabic: 'الصَّمَدُ', phonetic: 'As-Samad', meaning: 'L\'Immuable', explanation: 'Celui qui est sans besoin, autosuffisant et immuable. Tous ont besoin de Lui mais Lui n\'a besoin de personne.', bienfait: 'Celui qui comprend ce nom découvre la vanité des richesses terrestres et dirige son cœur vers la vraie suffisance en Dieu.'),
  NomAllah(number: 62, arabic: 'الْقَادِرُ', phonetic: 'Al-Qadir', meaning: 'Le Capable', explanation: 'Celui qui possède une puissance absolue sur tous les choses et dont le pouvoir ne connaît aucune limite. Rien ne dépasse sa capacité.', bienfait: 'Celui qui invoque ce nom avec confiance en cas de difficulté verra l\'impossible devenir possible par la grâce divine.'),
  NomAllah(number: 63, arabic: 'الْمُقْتَدِرُ', phonetic: 'Al-Muqtadir', meaning: 'Celui Qui a le Pouvoir', explanation: 'Celui qui dispose d\'un pouvoir et d\'une puissance manifeste et complète. Son pouvoir s\'étend sur tout sans nuance ni limitation.', bienfait: 'Méditer sur ce nom renforce la confiance du serviteur en l\'aide divine et dissipe les doutes concernant sa capacité à surmonter les obstacles.'),
  NomAllah(number: 64, arabic: 'الْمُعَجِّلُ', phonetic: 'Al-Mou\'ajjil', meaning: 'Celui Qui Accélère', explanation: 'Celui qui avance et accélère l\'arrivée des choses selon sa sagesse. Il peut accélérer la punition ou la récompense de celui qu\'il veut.', bienfait: 'Accepter ce nom avec patience apaise l\'inquiétude concernant le moment de l\'arrivée de la provision ou de la récompense.'),
  NomAllah(number: 65, arabic: 'الْمُؤَخِّرُ', phonetic: 'Al-Moakhkhir', meaning: 'Celui Qui Retarde', explanation: 'Celui qui retarde et ajourne les choses selon son plan divin. Il diffère parfois ce qui semble urgent pour une sagesse cachée.', bienfait: 'Celui qui accepte les retards en invoquant ce nom trouvera la sagesse dans l\'attente et développera la patience vertueuse.'),
  NomAllah(number: 66, arabic: 'الْأَوَّلُ', phonetic: 'Al-Awal', meaning: 'Le Premier', explanation: 'Celui qui existe avant tout, sans commencement à son existence. Il est antérieur à toute création.', bienfait: 'Ce nom rappelle que toute chose nouvelle commence après Dieu, ancrant la conscience de la dépendance primordiale.'),
  NomAllah(number: 67, arabic: 'الْآخِرُ', phonetic: 'Al-Akhir', meaning: 'Le Dernier', explanation: 'Celui qui demeurera après la disparition de toute création. Il est la destination finale et la fin de tout.', bienfait: 'Réciter ce nom prépare l\'âme à l\'Au-delà et maintient la conscience que le vrai succès réside dans l\'éternité avec Dieu.'),
  NomAllah(number: 68, arabic: 'الظَّاهِرُ', phonetic: 'Az-Zahir', meaning: 'Le Manifeste', explanation: 'Celui qui est apparent et visible dans ses signes et ses créations, bien que son essence reste transcendante. Son existence et sa puissance sont manifestes.', bienfait: 'Celui qui médite sur ce nom percevra les signes de Dieu dans la création et raffinera son observation spirituelle.'),
  NomAllah(number: 69, arabic: 'الْبَاطِنُ', phonetic: 'Al-Batin', meaning: 'Le Caché', explanation: 'Celui dont l\'essence est complètement cachée et transcendante, imperceptible aux sens. Il est au-delà de toute compréhension créée.', bienfait: 'Accepter ce nom apaise le cœur en acceptant que les mystères divins dépassent la compréhension humaine.'),
  NomAllah(number: 70, arabic: 'الْوَالِي', phonetic: 'Al-Wali', meaning: 'Le Souverain', explanation: 'Celui qui gouverne absolument et qui est le maître suprême. Il administre les affaires de l\'univers avec sagesse et justice.', bienfait: 'Celui qui accepte l\'autorité de ce nom dans sa vie trouvera ordre et justice dans les circonstances apparemment chaotiques.'),
  NomAllah(number: 71, arabic: 'الْمُتَعَالِي', phonetic: 'Al-Mutaali', meaning: 'L\'Infiniment Haut', explanation: 'Celui qui transcende absolument toute création par sa hauteur et sa gloire. Il est élevé au-delà de toute comparaison et ressemblance.', bienfait: 'Méditer sur ce nom enseigne l\'humilité authentique en reconnaissant l\'immense distance entre la créature et le Créateur.'),
  NomAllah(number: 72, arabic: 'الْبِرُّ', phonetic: 'Al-Bir', meaning: 'La Vertu', explanation: 'Celui qui est bon et bienveillant envers sa création, qui manifeste la générosité et la justice. Sa bonté est constante et sans limite.', bienfait: 'Celui qui invoque ce nom avec sincérité développera la compassion envers autrui et la bonté deviendra sa nature.'),
  NomAllah(number: 73, arabic: 'التَّوَّابُ', phonetic: 'At-Tawwab', meaning: 'Celui Qui Pardonne', explanation: 'Celui qui accepte le repentir de ses serviteurs et qui les réadmet continuellement dans sa grâce. Son pardon ne s\'épuise jamais.', bienfait: 'Celui qui se repent sincèrement en invoquant ce nom trouvera la porte du pardon toujours ouverte à son retour.'),
  NomAllah(number: 74, arabic: 'الْحَفِيظُ', phonetic: 'Al-Hafiz', meaning: 'Le Gardien', explanation: 'Celui qui garde et protège sa création du changement, de l\'oubli et de la destruction. Il préserve tout ce qui existe.', bienfait: 'Celui qui place sa confiance en ce nom verra ses affaires protégées et ses intérêts préservés par le gardien divin.'),
  NomAllah(number: 75, arabic: 'الْعَالِي', phonetic: 'Al-Ali', meaning: 'Le Sublime', explanation: 'Celui qui est suprêmement élevé en essence, en attributs et en actions. Toute élévation créée lui est soumise et inférieure.', bienfait: 'Réciter ce nom élève l\'âme vers les réalités spirituelles supérieures et détache du matérialisme terrestre.'),
  NomAllah(number: 76, arabic: 'الْأَكْرَمُ', phonetic: 'Al-Akram', meaning: 'Le Plus Noble', explanation: 'Celui qui possède la noblesse suprême et la générosité absolue. Sa magnificence transcende toute concept de noblesse créée.', bienfait: 'Celui qui demande la noblesse de caractère en invoquant ce nom recevra l\'honneur véritable de l\'intégrité morale.'),
  NomAllah(number: 77, arabic: 'اَلرَّقِيب', phonetic: 'Ar-Raqib', meaning: 'Le Vigilant', explanation: 'Celui qui surveille constamment et attention toutes ses créatures. Aucune action n\'échappe à sa vigilance constante.', bienfait: 'Sachant qu\'il est vigilant, le serviteur purifiera ses actions internes et maintiendra l\'intégrité en secret comme en public.'),
  NomAllah(number: 78, arabic: 'الْقِيَّام', phonetic: 'Al-Qiyam', meaning: 'Celui Qui Gère', explanation: 'Celui qui gère et administre les affaires de sa création sans cesse. Il maintient l\'ordre de l\'univers par son gestion sagesse.', bienfait: 'Invoquer ce nom apaise l\'inquiétude en reconnaissant que la gestion de tous les affaires appartient ultimement à Dieu.'),
  NomAllah(number: 79, arabic: 'الرَّقِيقُ', phonetic: 'Ar-Raqiq', meaning: 'Le Délicat', explanation: 'Celui dont la miséricorde est délicate et subtile, qui touche le cœur doucement. Sa bonté couvre les créatures avec une tendresse infinie.', bienfait: 'Méditer sur ce nom apaise le cœur blessé en le remplissant de la tendresse infinie de la miséricorde divine.'),
  NomAllah(number: 80, arabic: 'الْقَدِيرُ', phonetic: 'Al-Qadir', meaning: 'Le Puissant', explanation: 'Celui qui possède le pouvoir absolu et qui peut accomplir toute chose. Aucune difficulté ne peut le dépasser.', bienfait: 'Celui qui se tourne vers ce nom en cas de difficulté trouvera la force et la capacité de surmonter n\'importe quel obstacle.'),
  NomAllah(number: 81, arabic: 'السِّتِّيرُ', phonetic: 'As-Sittir', meaning: 'Celui Qui Voile', explanation: 'Celui qui voile les fautes de ses serviteurs et ne les expose pas publiquement. Il couvre avec miséricorde les défauts de ses créatures.', bienfait: 'Celui qui garde les secrets des autres et voile leurs défauts recevra le voilement divin sur ses propres fautes.'),
  NomAllah(number: 82, arabic: 'الْعَفُوُّ', phonetic: 'Al-Afu', meaning: 'Celui Qui Pardonne', explanation: 'Celui qui pardonne largement et efface les péchés entièrement, qui annule le châtiment mérité. Son pardon est complet.', bienfait: 'Celui qui pardonne sincèrement aux autres en invoquant ce nom recevra le pardon complet de ses propres erreurs.'),
  NomAllah(number: 83, arabic: 'الرَّؤُوفُ', phonetic: 'Ar-Rauf', meaning: 'Celui Qui est Doux', explanation: 'Celui qui manifeste une douceur et une tendresse extrêmes dans sa miséricorde. Son traitement est plein de compassion délicate.', bienfait: 'Celui qui se repent en invoquant ce nom trouvera Dieu doux et compatissant envers ses défauts et son faiblesses.'),
  NomAllah(number: 84, arabic: 'مَالِكُ الْمُلْكِ', phonetic: 'Malik-ul-Mulk', meaning: 'Le Maître du Domaine', explanation: 'Celui qui possède la royauté et la domination absolues. Tout pouvoir créé est un emprunt temporaire de sa royauté éternelle.', bienfait: 'Méditer sur ce nom purifie le cœur de l\'attachement aux pouvoirs terrestres temporels et oriente vers l\'éternel.'),
  NomAllah(number: 85, arabic: 'ذُو الْجَلَالِ وَالْإِكْرَامِ', phonetic: 'Dhu-al-Jalal wa-al-Ikram', meaning: 'Possesseur de Gloire et d\'Honneur', explanation: 'Celui qui possède une gloire majestueuse et une grandeur honorable. Ses gloire et honneur sont absolus et inviolables.', bienfait: 'Réciter ce nom avec révérence renforce le respect divin et élève l\'âme vers la contemplation de la magnificence divine.'),
  NomAllah(number: 86, arabic: 'الْمُقْسِطُ', phonetic: 'Al-Muqsit', meaning: 'Celui Qui Rend Justice', explanation: 'Celui qui rend justice avec équité et impartialité à tous ses serviteurs. Sa justice est parfaite et sans favoritisme.', bienfait: 'Celui qui demande la justice en invoquant ce nom verra l\'équité triompher même si la tyrannie semble temporairement dominante.'),
  NomAllah(number: 87, arabic: 'الجَمِيعُ', phonetic: 'Al-Jami', meaning: 'Celui Qui Rassemble', explanation: 'Celui qui rassemble toutes choses et rassemble l\'humanité pour le jugement. Il unifie et coordonne l\'ordre de l\'univers.', bienfait: 'Invoquer ce nom attire l\'unité et la cohésion dans les affaires fragmentées et dispersées du serviteur.'),
  NomAllah(number: 88, arabic: 'الْغَنِيُّ', phonetic: 'Al-Ghani', meaning: 'Le Riche', explanation: 'Celui qui est complètement exempt du besoin et qui est autosuffisant absolument. Sa richesse infinie contraste avec la pauvreté créée.', bienfait: 'Celui qui médite sur ce nom comprendra la véritable pauvreté de la création et se libèrera de l\'avidité matérielle.'),
  NomAllah(number: 89, arabic: 'الْمُغْنِي', phonetic: 'Al-Moughni', meaning: 'Celui Qui Enrichit', explanation: 'Celui qui enrichit ses serviteurs et pourvoit à leur suffisance. Il est la source de toute abondance créée.', bienfait: 'Celui qui invoque ce nom régulièrement avec gratitude attirera l\'enrichissement spirituel et matériel dans sa vie.'),
  NomAllah(number: 90, arabic: 'الْمَانِعُ', phonetic: 'Al-Mani', meaning: 'Celui Qui Refuse', explanation: 'Celui qui retient et refuse ses faveurs selon sa sagesse. Il peut empêcher le mal d\'atteindre ses serviteurs.', bienfait: 'Accepter ce nom apaise le cœur en sachant que tout refus ou privation peut contenir une protection divine.'),
  NomAllah(number: 91, arabic: 'الضَّارُّ', phonetic: 'Ad-Dar', meaning: 'Celui Qui Nuit', explanation: 'Celui qui cause le dommage et la souffrance selon sa sagesse et sa justice. Tout mal vient de lui selon le décret divin.', bienfait: 'Celui qui accepte ce nom avec patience et sincérité trouvera dans le dommage apparent une miséricorde cachée et une correction divine.'),
  NomAllah(number: 92, arabic: 'النَّافِعُ', phonetic: 'An-Nafi', meaning: 'Celui Qui Bénéficie', explanation: 'Celui qui procure le bénéfice et l\'avantage à qui il veut. Tout bien et profit vient uniquement de sa volonté.', bienfait: 'Celui qui demande le bénéfice en invoquant ce nom verra les portes du profit et de l\'utilité s\'ouvrir pour lui.'),
  NomAllah(number: 93, arabic: 'النُّورُ', phonetic: 'An-Nur', meaning: 'La Lumière', explanation: 'Celui qui est la source de toute lumière physique et spirituelle. Sa lumière illumine tous les univers et les esprits.', bienfait: 'Celui qui demande l\'illumination du cœur en invoquant ce nom trouvera guidance et clarté dans les affaires obscures.'),
  NomAllah(number: 94, arabic: 'الْهَادِي', phonetic: 'Al-Hadi', meaning: 'Le Guide', explanation: 'Celui qui guide ses créatures vers le chemin droit et vers lui-même. Sa guidance est parfaite et sans erreur.', bienfait: 'Celui qui demande la guidance sincèrement en invoquant ce nom sera dirigé vers le chemin de la vérité et de la rectitude.'),
  NomAllah(number: 95, arabic: 'الْبَدِيعُ', phonetic: 'Al-Badi', meaning: 'Celui Qui Crée l\'Imprévu', explanation: 'Celui qui crée des choses merveilleuses et sans précédent. Il combine les créations de manière surprenante et originale.', bienfait: 'Méditer sur ce nom remplit le cœur de l\'émerveillement devant l\'infinie créativité divine et l\'unicité de chaque créature.'),
  NomAllah(number: 96, arabic: 'الْبَاقِي', phonetic: 'Al-Baqi', meaning: 'L\'Éternel', explanation: 'Celui qui demeure et persiste éternellement, tandis que toute création disparaît. Son existence éternelle transcende le temps.', bienfait: 'Réciter ce nom prépare le cœur à l\'éternité en rappelant que seule la permanence divine mérite l\'attachement véritable.'),
  NomAllah(number: 97, arabic: 'الْوَارِثُ', phonetic: 'Al-Warith', meaning: 'L\'Héritier', explanation: 'Celui qui héritera de toute création après sa fin. À la fin, seul il demeurera éternel après la destruction de tout.', bienfait: 'Celui qui comprend ce nom renonce à l\'attachement aux biens terrestres sachant que l\'héritage final appartient à Dieu seul.'),
  NomAllah(number: 98, arabic: 'الرَّشِيدُ', phonetic: 'Ar-Rashid', meaning: 'Celui Qui Conseille', explanation: 'Celui qui guide vers la rectitude et le bon conseil divin. Sa guidance est juste et exempte d\'erreur.', bienfait: 'Celui qui demande le bon conseil en invoquant ce nom recevra la guidance vers les meilleures décisions et actions.'),
  NomAllah(number: 99, arabic: 'الصَّبُورُ', phonetic: 'As-Sabur', meaning: 'Le Patient', explanation: 'Celui qui tolère les péchés de ses créatures sans se hâter à les châtier. Sa patience infinie permet la repentance et l\'amélioration.', bienfait: 'Celui qui demande la patience en invoquant ce nom développera la endurance spirituelle et morale face aux épreuves de la vie.'),
];
